import csv, re, os, sys
os.chdir('/home/jess/Documents/primary_juvenile_meta-analysis')
RES='data/inference_test/results/sonnet-5-5_raw.csv'
COLS=next(csv.reader(open(RES)))
def paper_text(stem):
    return re.sub(r'\s+',' ',open(f'data/papers_test/md_llm/{stem}.md').read())
def add(stem, common, rows, loc_prefix=None):
    """common: dict of paper-wide cols (source, supplementary_material, notes_tail...). rows: list of dicts; key 'dl' = list of (loc, quote)."""
    txt=paper_text(stem)
    out=[]; bad=0
    for r in rows:
        d={c:'' for c in COLS}
        d.update(common); d.update({k:v for k,v in r.items() if k not in('dl','notes')})
        d['file_name']=stem
        dl=r.get('dl',[])
        d['data_location']='; '.join(l for l,q in dl)
        d['data_quote']='; '.join(f'[{l}] {q}' for l,q in dl)
        for l,q in dl:
            for part in q.split(' ... '):
                if re.sub(r'\s+',' ',part).strip() not in txt:
                    print('QUOTE NOT FOUND:',stem,part[:100]); bad+=1
        n=r.get('notes','')
        tail=common.get('notes_tail','')
        d['notes']='; '.join(x for x in (n,tail) if x)
        d.pop('notes_tail',None)
        out.append(d)
    if bad: print('ABORT',bad); sys.exit(1)
    with open(RES,'a',newline='') as f:
        w=csv.DictWriter(f,fieldnames=COLS,extrasaction='ignore',lineterminator='\n'); 
        for d in out: w.writerow(d)
    print('wrote',len(out))
def na(stem, reason, source=None, supp='NA'):
    d={c:'NA' for c in COLS}
    d.update(notes=reason, source=source or stem, file_name=stem, supplementary_material=supp)
    with open(RES,'a',newline='') as f:
        csv.DictWriter(f,fieldnames=COLS,lineterminator='\n').writerow(d)
def log(stem,status,n,started,finished,note=''):
    with open('data/inference_test/logs/sonnet-5-5_log.csv','a',newline='') as f:
        csv.writer(f,lineterminator='\n').writerow([stem,status,n,started,finished,note,'','','','','',''])
def strip_rows(stem):
    rows=list(csv.DictReader(open(RES)))
    keep=[r for r in rows if r['file_name']!=stem]
    with open(RES,'w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=COLS,lineterminator='\n'); w.writeheader(); w.writerows(keep)
    return len(rows)-len(keep)
E
